def process_list(data):
    items = data.split(',')
    unique_items = []
    for item in items:
        if item not in unique_items:
            unique_items.append(item)
    return ','.join(unique_items)

def main():
    input_data = 'a,b,a,c,b'
    result = process_list(input_data)
    print(result)

if __name__ == '__main__':
    main()

